// app.js – hardened version
require('dotenv').config();               // Load .env files (ignore in prod if not needed)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ---------------------------
// 1️⃣  Security middlewares
// ---------------------------
app.use(helmet()); // sets a solid set of security headers

// Rate limiting – 100 requests per 15 min per IP (tweak for your traffic)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS – whitelist via env var (comma‑separated list)
// Example: ALLOWED_ORIGINS="https://example.com,https://app.example.com"
const whitelist = (process.env.ALLOWED_ORIGINS || '')
  .split(',')
  .filter(Boolean);
app.use(
  cors({
    origin: function (origin, callback) {
      // allow non‑browser requests (e.g., curl, Postman) when origin is undefined
      if (!origin || whitelist.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
  })
);

// ---------------------------
// 2️⃣  Routes
// ---------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // NOTE: In a real product you would probably NOT expose raw e‑mail addresses.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  res.json(users);
});

// ---------------------------
// 3️⃣  Global error handler
// ---------------------------
app.use((err, _req, res, _next) => {
  console.error(err); // replace with a structured logger in prod
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
  });
});

// ---------------------------
// 4️⃣  Server start
// ---------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

**What this patch adds**

* Environment loading (`dotenv`) – keep credentials out of source.  
* Helmet – all the standard security headers.  
* Rate limiting – basic DoS protection.  
* Configurable CORS – prevents unrestricted cross‑origin calls.  
* Centralized error handler – avoids leaking stack traces.  
* Port from an environment variable – easier to run in containers / PaaS.  

