## 2. Recommended Fixes

Below is a sample “secure baseline” implementation that addresses the above points. You can paste it directly into `app.js` (or create a new file and require it).

```js
// ==== Secure Express Boilerplate (app.js) ====

// Core modules
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan'); // optional, for logging
require('dotenv').config(); // Load .env variables (if any)

const app = express();

// -------------------
// 1. Security middlewares
// -------------------

// Helmet sets a collection of secure HTTP headers
app.use(helmet());

// Enable CORS only for trusted origins (adjust as needed)
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser tools (like health checks) with no origin
      if (!origin) return callback(null, true);
      if (allowedOrigins.length === 0) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'), false);
    },
  })
);

// Rate limiting – 100 requests per 15 minutes per IP (adjust for your use‑case)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Basic request logging (helps with forensic analysis)
app.use(morgan('combined'));

// -------------------
// 2. Routes
// -------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * In a real product this endpoint would be protected (auth + RBAC)
 * and the e‑mail addresses would be omitted or hashed.
 */
app.get('/users', (req, res) => {
  // Example: hide sensitive fields if not authenticated
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// -------------------
// 3. Centralised error handling
// -------------------
app.use((err, _req, res, _next) => {
  // Do NOT leak stack traces in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// -------------------
// 4. Server start (HTTPS recommended in production)
// -------------------
const PORT = process.env.PORT || 3000;
if (require.main === module) {
  // When run directly: start HTTP server (dev only)
  app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

// Export for testing or external composition
module.exports = app;
```

### What each addition does
| Addition | Purpose |
|----------|---------|
| `helmet` | Sets essential security headers automatically. |
| `cors` with whitelist | Prevents other origins from consuming the API unintentionally. |
| `express-rate-limit` | Mitigates brute‑force, credential stuffing, and simple DoS attacks. |
| `morgan` | Logs requests; useful for audit trails and detecting abnormal traffic. |
| Centralized error handler | Hides stack traces in production, avoiding information leakage. |
| `dotenv` + environment variables | Allows flexible configuration (port, CORS origins, etc.) without code changes. |
| Conditional `app.listen` guard (`require.main === module`) | Makes the file safe to `require` elsewhere (e.g., unit tests) without unintentionally starting a server. |
| **Removed plain e‑mail addresses** in `/users` | Demonstrates the principle of “least privilege” – only expose data that’s needed. |
| **HTTPS recommendation** | In production you should terminate TLS at a reverse proxy (NGINX, HAProxy, cloud LB) or use `https.createServer`. |

