const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ---------- Middleware ----------
app.use(helmet()); // Sets a robust set of security headers

// Simple CORS policy – adjust origins as needed
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || '*', // Use a specific origin in prod
  methods: ['GET'],
}));

// Rate limiting – protects health and public endpoints from brute‑force / DoS
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

app.get('/users', (req, res) => {
  // NOTE: In a real app this should be behind authentication/authorization.
  // For demo purposes we keep the static payload.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------- Error handling ----------
app.use((err, _req, res, _next) => {
  console.error(err); // In prod, consider a logging service (e.g., Winston + Loggly)
  res.status(500).json({ error: 'Internal Server Error' });
});

// Export the app without auto‑starting a listener.
// This makes it safe to `require('./app')` in tests or other modules.
