## How to externalise the identified literals

Below is a concise example of how you could refactor the existing file to replace the hard‑coded values with environment variables (using `dotenv` for local development). This example builds on the previously suggested security patch.

```js
// -------------------------------------------------
// Load environment variables (development only)
// -------------------------------------------------
require('dotenv').config();   // <-- add `dotenv` to dependencies

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// -------------------------------------------------
// Configuration (read from env, with sane defaults)
// -------------------------------------------------
const PORT          = process.env.PORT || 3000;
const CORS_ORIGIN   = process.env.CORS_ORIGIN || '*';
const RATE_WINDOW   = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000; // 15 min
const RATE_MAX      = parseInt(process.env.RATE_LIMIT_MAX, 10) || 100;

// -------------------------------------------------
// Middleware stack
// -------------------------------------------------
app.use(helmet());
app.use(cors({ origin: CORS_ORIGIN, methods: ['GET', 'POST', 'OPTIONS'] }));
app.use(morgan('combined'));
app.use(
  rateLimit({
    windowMs: RATE_WINDOW,
    max: RATE_MAX,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// -------------------------------------------------
// Routes
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // USER DATA SHOULD COME FROM A DATABASE / secure store.
  // The e‑mail field is removed to avoid leaking PII.
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// -------------------------------------------------
// Server start & graceful shutdown
// -------------------------------------------------
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

function shutdown(signal) {
  console.log(`Received ${signal}. Shutting down...`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

module.exports = app;
```

